const input = $input.first().json;
const body = input.body || input;
const { id, estado, estado_motivo, resumen, disponibilidad, tags, proxima_cita, notas } = body;

if (!id) {
  throw new Error('Falta el campo requerido: id');
}

const isValid = (v) => v && v !== 'Sin definir' && v !== '' && v !== null;
const toSql = (v) => isValid(v) ? `'${String(v).replace(/'/g, "''")}'` : 'null';

const updates = [];
if (estado) updates.push(`estado = '${estado}'`);
if (isValid(estado_motivo)) updates.push(`estado_motivo = ${toSql(estado_motivo)}`);
if (isValid(resumen)) updates.push(`resumen = ${toSql(resumen)}`);
if (isValid(disponibilidad)) updates.push(`disponibilidad = ${toSql(disponibilidad)}`);
if (isValid(tags)) updates.push(`tags = '${tags}'`);
if (isValid(proxima_cita)) updates.push(`proxima_cita = '${proxima_cita}'::timestamp`);
else if (proxima_cita === 'Sin definir') updates.push(`proxima_cita = null`);
if (isValid(notas)) updates.push(`notas = ${toSql(notas)}`);

updates.push('estado_fecha = CURRENT_TIMESTAMP');
updates.push('ultimo_contacto = CURRENT_TIMESTAMP');
updates.push('updated_at = CURRENT_TIMESTAMP');

const query = `UPDATE leads SET ${updates.join(', ')} WHERE id = ${parseInt(id)} RETURNING id, nombre, whatsapp, estado, estado_motivo, updated_at;`;

return [{json: {query}}];

const result = $('PostgreSQL - Update').first().json;

if (!result || !result.id) {
  return [{json: {success: false, message: 'Lead no encontrado'}}];
}

return [{json: {success: true, message: 'Lead actualizado correctamente', lead: {id: result.id, nombre: result.nombre, estado: result.estado, estado_motivo: result.estado_motivo}}}];
